PPC_FUNC_IMPL(__imp__sub_82002000) {
	PPC_FUNC_PROLOGUE();
	// lwz r3,0(r31)
	ctx.r3.u64 = PPC_LOAD_U32(ctx.r31.u32 + 0);
	{
		// a DEFAULT-ON switch is not a gate: the edit runs in the default exe
		static const bool s_on = [] {
			const char* e = std::getenv("SR_FIXTURE_D18_ON");
			return !e || e[0] != '0';
		}();
		if (s_on) {
			sr::kernel::writeGuestBE32(ctx.r3.u32, 1u);  // EXPECT-GEN: UNGATED-FAIL
		}
	}
	{
		// an opt-in diagnostic IS a gate
		const char* d = std::getenv("SR_FIXTURE_D18_DIAG");
		if (d && d[0] == '1') {
			sr::kernel::writeGuestBE32(ctx.r3.u32, 2u);  // EXPECT-GEN: GATED
		}
	}
	// the master gate in an UNRELATED branch above does not gate the edit
	if (sr::kernel::forcingAllowed()) {
		sr::kernel::logX("forcing on");  // EXPECT-GEN: GATED
	}
	sr::kernel::writeGuestBE32(ctx.r3.u32, 3u);  // EXPECT-GEN: UNGATED-FAIL
	// a host writer called WITHOUT sr::kernel:: is a hand edit too
	extern void helperWriter(uint32_t va);  // EXPECT-GEN: NOSITE
	helperWriter(ctx.r3.u32);  // EXPECT-GEN: UNGATED-FAIL
	// a qualified host writer (not writeGuest*) is forcing too
	sr::kernel::helperWriter(ctx.r3.u32 + 4);  // EXPECT-GEN: UNGATED-FAIL
	if (sr::kernel::forcingAllowed()) {
		sr::kernel::helperWriter(ctx.r3.u32 + 8);  // EXPECT-GEN: GATED
	}
	// blr
	return;
}
